patches.value:
query project($id: String!) {
  project(id: $id) {
    baseEnvironmentId
    createdAt
    deletedAt
    description
    id
    name
    primaryEnvironmentId
    updatedAt
    workspaceId
    services(first: 50) {
      edges {
        node {
          createdAt
          deletedAt
          groupId
          id
          name
          projectId
          templateId
        }
      }
    }
    buckets(first: 50) {
      edges {
        node {
          createdAt
          groupId
          id
          name
          projectId
          updatedAt
        }
      }
    }
    groups(first: 50) {
      edges {
        node {
          color
          groupId
          icon
          id
          isCollapsed
          name
          projectId
        }
      }
    }
  }
}
